class Solution {
    int m, n;
    void flood(int r, int c, std::vector<std::vector<int>>& grid) {
        if (r < 0 || r >= m || c < 0 || c >= n || grid[r][c] == 1) return;
        grid[r][c] = 1;
        flood(r + 1, c, grid);
        flood(r - 1, c, grid);
        flood(r, c + 1, grid);
        flood(r, c - 1, grid);
    }
public:
    int closedIsland(std::vector<std::vector<int>>& grid) {
        m = grid.size();
        n = grid[0].size();
        for (int i = 0; i < m; ++i) {
            if (grid[i][0] == 0) flood(i, 0, grid);
            if (grid[i][n - 1] == 0) flood(i, n - 1, grid);
        }
        for (int j = 0; j < n; ++j) {
            if (grid[0][j] == 0) flood(0, j, grid);
            if (grid[m - 1][j] == 0) flood(m - 1, j, grid);
        }
        int ans = 0;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == 0) {
                    ans++;
                    flood(i, j, grid);
                }
            }
        }
        return ans;
    }
};

